style.css:
@-moz-document domain("ya.ru"), domain("yandex.ru") {
* { font-family: Tahoma, sans-serif !important; border-radius: 0 !important; }

body { background: #008080 !important; }

/* Шапка */
header, [class*="Header"] {
  background: #000080 !important;
  border-bottom: 2px outset #fff !important;
}

header *, [class*="Header"] * { color: #fff !important; }

/* Поиск */
input[type="search"], input[type="text"], [class*="search"] input {
  background: #fff !important;
  border: 2px inset #808080 !important;
  padding: 6px !important;
  font-size: 14px !important;
}

/* Кнопки */
button, [class*="button"] {
  background: #c0c0c0 !important;
  border: 2px outset #fff !important;
  padding: 6px 12px !important;
  font-weight: bold !important;
}

button:active { border: 2px inset #fff !important; }

/* Виджеты */
[class*="card"], [class*="widget"] {
  background: #c0c0c0 !important;
  border: 2px outset #fff !important;
  box-shadow: 2px 2px 0 #000 !important;
}

[class*="card"] > div:first-child {
  background: #000080 !important;
  color: #fff !important;
  padding: 4px 8px !important;
  font-weight: bold !important;
}

/* Ссылки */
a { color: #0000ff !important; text-decoration: underline !important; }
a:visited { color: #800080 !important; }
a:hover { color: #ff0000 !important; background: #ffff00 !important; }

/* Скроллбар */
::-webkit-scrollbar { width: 16px !important; }
::-webkit-scrollbar-track { background: #c0c0c0 !important; }
::-webkit-scrollbar-thumb { background: #c0c0c0 !important; border: 2px outset #fff !important; }

/* Выделение */
::selection { background: #000080 !important; color: #fff !important; }
}
